function normalize(str) {
  return String(str || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd')
    .replace(/Đ/g, 'D')
    .trim();
}

function getTelegramContext(source) {
  const payload = source.payload || {};
  const message = source.message || payload.message || payload.body?.message || {};
  const chatId = source.chatId || message.chat?.id || payload.chatId || '';
  const rawText = String(
    source.rawText ||
    source.text ||
    message.text ||
    message.caption ||
    payload.text ||
    ''
  ).trim();

  return { payload, message, chatId, rawText };
}

function cleanName(value) {
  return String(value || '')
    .trim()
    .replace(/^["'“”‘’]+|["'“”‘’]+$/g, '')
    .replace(/\s+/g, ' ');
}

function parseSheetTab(rawText) {
  const text = String(rawText || '').trim();

  // Hỗ trợ: tab Data, sheet tab Data, trang tính Data
  const match = text.match(/\b(?:tab|sheet tab|trang tinh|worksheet)\s+["'“”‘’]?([^:"'“”‘’]+?)["'“”‘’]?(?:\s*:|\s|$)/i);
  if (!match) return '';

  return cleanName(match[1]);
}

function parseAppendCommand(rawText) {
  const original = String(rawText || '').trim();
  const normalized = normalize(original);

  const prefixes = [
    'them dong vao sheet',
    'them dong sheet',
    'them dong vao bang tinh',
    'append row sheet',
    'append row',
    'add row sheet',
    'add row'
  ];

  let bodyOriginal = original;
  let bodyNormalized = normalized;

  for (const prefix of prefixes) {
    if (bodyNormalized.startsWith(prefix + ' ')) {
      bodyOriginal = original.slice(prefix.length + 1).trim();
      bodyNormalized = normalized.slice(prefix.length + 1).trim();
      break;
    }

    if (bodyNormalized === prefix) {
      return { sheetName: '', rowData: '' };
    }
  }

  const colonIndex = bodyOriginal.indexOf(':');
  if (colonIndex === -1) {
    return {
      sheetName: cleanName(bodyOriginal),
      rowData: ''
    };
  }

  let sheetName = bodyOriginal.slice(0, colonIndex).trim();
  const rowData = bodyOriginal.slice(colonIndex + 1).trim();

  const tab = parseSheetTab(sheetName);
  if (tab) {
    sheetName = sheetName
      .replace(/\b(?:tab|sheet tab|trang tinh|worksheet)\s+["'“”‘’]?[^:"'“”‘’]+?["'“”‘’]?$/i, '')
      .trim();
  }

  return {
    sheetName: cleanName(sheetName),
    rowData,
    sheetTab: tab
  };
}

function parseCsvLine(line) {
  const input = String(line || '');
  const values = [];
  let current = '';
  let inQuotes = false;

  for (let i = 0; i < input.length; i++) {
    const char = input[i];
    const next = input[i + 1];

    if (char === '"' && inQuotes && next === '"') {
      current += '"';
      i++;
      continue;
    }

    if (char === '"') {
      inQuotes = !inQuotes;
      continue;
    }

    if (char === ',' && !inQuotes) {
      values.push(current.trim());
      current = '';
      continue;
    }

    current += char;
  }

  values.push(current.trim());
  return values.filter((value) => value !== '');
}

const source = $('Execute Workflow Trigger').item.json || {};
const ctx = getTelegramContext(source);
const raw = ctx.rawText;

const parsed = parseAppendCommand(raw);

const spreadsheetId =
  source.spreadsheetId ||
  source.sheetId ||
  source.fileId ||
  source.targetId ||
  ctx.payload.spreadsheetId ||
  ctx.payload.sheetId ||
  ctx.payload.fileId ||
  '';

const sheetTab =
  source.sheetTab ||
  ctx.payload.sheetTab ||
  parsed.sheetTab ||
  '';

const sheetName = cleanName(
  source.sheetName ||
  source.fileName ||
  source.title ||
  source.query ||
  ctx.payload.sheetName ||
  ctx.payload.fileName ||
  ctx.payload.title ||
  ctx.payload.query ||
  parsed.sheetName ||
  ''
);

const rowData = String(
  source.rowData ||
  source.content ||
  ctx.payload.rowData ||
  ctx.payload.content ||
  parsed.rowData ||
  ''
).trim();

const values = Array.isArray(source.values)
  ? source.values
  : parseCsvLine(rowData);

const hasTarget = Boolean(spreadsheetId || sheetName);
const hasContent = values.length > 0;

return [{
  json: {
    ...source,
    payload: ctx.payload,
    message: ctx.message,
    chatId: ctx.chatId,
    rawText: raw,
    text: normalize(raw),

    spreadsheetId,
    sheetId: spreadsheetId,
    sheetName,
    query: sheetName,
    sheetTab,

    rowData,
    values,

    hasTarget,
    hasContent,
    response: hasTarget && hasContent
      ? ''
      : '📊 <b>Thêm dòng vào Google Sheet</b>\n\nVí dụ:\n<code>thêm dòng vào sheet Chi tiêu: cafe,30000,ăn uống</code>\n<code>thêm dòng vào sheet Chi tiêu tab Data: cafe,30000,ăn uống</code>'
  }
}];

const source = $('Prepare Action').item.json || {};

function escapeHtml(value = '') {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

const rows = $input
  .all()
  .map((item) => item.json || {})
  .filter((item) => item.id || item.name);

if (!rows.length) {
  return [{
    json: {
      ...source,
      spreadsheetId: '',
      sheetId: '',
      found: false,
      response: 'Không tìm thấy Google Sheet phù hợp với: <b>' + escapeHtml(source.sheetName || source.query || '') + '</b>'
    }
  }];
}

const sheet = rows[0];

return [{
  json: {
    ...source,
    ...sheet,

    found: true,
    spreadsheetId: sheet.id || source.spreadsheetId || '',
    sheetId: sheet.id || source.sheetId || '',
    sheetName: sheet.name || source.sheetName || source.query || '',
    query: source.query || source.sheetName || '',
    webViewLink: sheet.webViewLink || source.webViewLink || '',
    mimeType: sheet.mimeType || source.mimeType || '',
    sheetTab: source.sheetTab || '',
    values: source.values || [],
    chatId: source.chatId || ''
  }
}];

function escapeHtml(value = '') {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/\"/g, '&quot;');
}

function getJson(nodeName) {
  try {
    return $(nodeName).item.json || {};
  } catch (e) {
    return {};
  }
}

const source = {
  ...getJson('Prepare Action'),
  ...getJson('Resolve Search Result')
};

const result = $input.item.json || {};

const sheetId =
  source.spreadsheetId ||
  source.sheetId ||
  '';

const link =
  source.webViewLink ||
  (sheetId ? `https://docs.google.com/spreadsheets/d/${sheetId}/edit` : '');

const chatId =
  source.chatId ||
  result.chatId ||
  '';

if (!chatId) {
  throw new Error('Missing chatId while formatting Google Sheets append response.');
}

const updatedRange =
  result.updates?.updatedRange ||
  result.updatedRange ||
  '';

const shownTarget = source.sheetTab
  ? `${source.sheetName || 'Không rõ tên'} / tab ${source.sheetTab}`
  : (source.sheetName || 'Không rõ tên');

const addedColumns = Array.isArray(source.values) ? source.values.length : 0;

let text = '✅ <b>Đã thêm dòng vào Google Sheet</b>\n\n';

text += `<b>${escapeHtml(shownTarget)}</b>\n`;

if (sheetId) {
  text += `ID: <code>${escapeHtml(sheetId)}</code>\n`;
}

if (updatedRange) {
  text += `Vùng cập nhật: <code>${escapeHtml(updatedRange)}</code>\n`;
}

text += `Số cột đã thêm: ${escapeHtml(addedColumns)}\n`;

if (link) {
  text += `🔗 <a href="${escapeHtml(link)}">Mở bảng tính</a>`;
}

return [{
  json: {
    chatId,
    text: text.trim()
  }
}];
